//! The CDDL ([RFC 8610]) of the values this crate decodes: for each type, the
//! data items its decoder accepts, as a CDDL document whose first rule is the
//! type's ([`document`]).
//!
//! A derived type's rule is generated by `#[derive(CBORCddl)]` from the same
//! parsed schema as its symbolic and bounded decoders (`dcbor-derive`'s
//! `Schema`): field keys, optional fields, unknown keys, variants, tag. It is
//! never written by hand, so no second description of a type exists to fall
//! out of step with its decoder. A field's type contributes its own rule
//! through its own [`Cddl`] implementation, a generic type's at each
//! instantiation.
//!
//! # What a rule denotes
//!
//! A rule denotes a set of CBOR data items at the data model level. A dCBOR
//! decoder accepts only dCBOR encodings of them (canonical form, numeric
//! reduction, NFC text, no `undefined`): the draft's `.dcbor` control
//! operator (draft-mcnally-deterministic-cbor, "CDDL support") adds exactly
//! that requirement to a byte string's embedded item. So the correspondence a
//! rule claims is over dCBOR-valid data items: such an item is accepted by
//! the type's decoder exactly when it matches the type's rule. Embedding a
//! type in a byte string is written `bstr .dcbor rule` by its user.
//!
//! # What has a rule
//!
//! Exactly the types whose accepted set CDDL can denote and whose rule has
//! an oracle independent of the decoder's own tables. Integers are their
//! ranges, text `tstr`, byte strings `bstr`, sequences arrays of their
//! element, maps tables of their key and value, a [`CBOR`] value `any`. The
//! floating-point types have none: their decoders accept an integer exactly
//! when the type represents it exactly (`float.rs`), a set no CDDL type
//! denotes (`number` admits every integer). Nor do [`crate::MinimalBigInt`]
//! (its leading-zero rule: no byte-string control requires a nonzero first
//! byte), [`crate::Date`] (tag 1 around a timestamp the float rule decodes)
//! or a hash set (its decoder refuses two elements converting to one, a
//! distinctness no CDDL array states): CDDL cannot name what each accepts.
//! Nor does [`crate::StabilizedText`], by the second criterion: a `.regexp`
//! class could name its assigned code points, but one generated from the
//! pinned table its decoder reads, with no independent check of it
//! (`tests/cddl`'s "The value classes it excludes" states each case with its
//! RFC 8610 sections). A derived type with
//! such a field has no rule: the derive's bound on the field's type is not
//! met, and the compiler says why (the diagnostic on [`Cddl`]). Pointers
//! (`Box`, `Rc`, `Arc`) have no decoder, so no rule either. A derived type
//! with a lifetime parameter has none: a rule is keyed by its type's
//! [`core::any::TypeId`], which only a `'static` type has; decoded types are
//! owned, so no decoded type is excluded by it.
//!
//! [RFC 8610]: https://www.rfc-editor.org/rfc/rfc8610

import_stdlib!();

use crate::{ByteString, CBOR, Map};

/// A type's CDDL: the type expression of `Self` where it is used, every rule
/// that expression names defined in `rules`.
///
/// Implemented exactly for the types whose accepted set CDDL denotes, with a
/// rule an oracle independent of the decoder's tables can check (the module's
/// "What has a rule"). A derived type with a field of any other type, a
/// float above all, does not compile, the diagnostic naming why (the
/// trybuild fixture `dcbor-derive/tests/ui/fail/cddl_float_field.rs` holds it).
#[diagnostic::on_unimplemented(
    message = "`{Self}` has no CDDL rule (see `dcbor::cddl`, \"What has a rule\")",
    label = "no CDDL rule for `{Self}`",
    note = "floating-point types, `MinimalBigInt`, `Date` and hash sets accept sets no CDDL \
            type denotes; a rule for `StabilizedText` would have no oracle independent of \
            its decoder's tables (see `dcbor::cddl`)"
)]
pub trait Cddl {
    /// The type expression of `Self`, defining in `rules` every rule it
    /// names.
    fn cddl(rules: &mut Rules) -> String;
}

/// The value of an optional map field when present: the type its `Option`
/// holds, the field absent when `None` (a derived map omits it, and its
/// decoder reads its absence as `None`). Used by the derive for a field of
/// type `Option<T>`; never `T / null`, since a present `null` is refused as
/// `T`'s wrong type.
pub trait Present {
    /// The present value's expression ([`Cddl::cddl`]).
    fn cddl(rules: &mut Rules) -> String;
}

impl<T: Cddl> Present for Option<T> {
    fn cddl(rules: &mut Rules) -> String {
        T::cddl(rules)
    }
}

/// The rules of one CDDL document, in the order their types were first
/// reached: one per derived type, a generic type's one per instantiation.
#[derive(Debug, Default)]
pub struct Rules {
    /// Each rule: the type it describes, by its [`core::any::TypeId`] (the
    /// one identity of a type; a type name may be shared by distinct types),
    /// its rule name, and its definition, written once the type's expression
    /// is complete.
    rules: Vec<(core::any::TypeId, String, String)>,
}

impl Rules {
    pub fn new() -> Self {
        Self::default()
    }

    /// The name of the rule describing `T`, defined once: on its first use,
    /// a name from `base` (the type's identifier, a CDDL identifier), and
    /// `define`'s expression as its definition. The name is registered before
    /// `define` runs, so a type that contains itself names its own rule. A
    /// second type of the same identifier (another instantiation of a
    /// generic type, or a type of another module) is given `base` with its
    /// ordinal, `-2` onwards. Used by the derive.
    #[doc(hidden)]
    pub fn rule<T: ?Sized + 'static>(
        &mut self,
        base: &str,
        define: impl FnOnce(&mut Rules) -> String,
    ) -> String {
        let key = core::any::TypeId::of::<T>();
        if let Some((_, name, _)) = self
            .rules
            .iter()
            .find(|(described, _, _)| *described == key)
        {
            return name.clone();
        }
        let base = base.strip_prefix("r#").unwrap_or(base);
        let mut name = base.to_string();
        let mut ordinal = 1;
        while self.rules.iter().any(|(_, taken, _)| *taken == name) {
            ordinal += 1;
            name = format!("{base}-{ordinal}");
        }
        let index = self.rules.len();
        self.rules.push((key, name.clone(), String::new()));
        let definition = define(self);
        self.rules[index].2 = definition;
        name
    }
}

/// The name of a document's first rule, which describes the type the
/// document is of. Not a Rust identifier, so no derived rule takes it.
pub const ROOT: &str = "dcbor-root";

/// The CDDL document of `T`: its first rule ([`ROOT`]) is `T`'s expression,
/// followed by every rule that expression names, in the order they were
/// reached. A validator takes the first rule as the document's root
/// (RFC 8610, section 3.1).
pub fn document<T: Cddl + ?Sized>() -> String {
    let mut rules = Rules::new();
    let root = T::cddl(&mut rules);
    let mut document = format!("{ROOT} = {root}\n");
    for (_, name, definition) in &rules.rules {
        document.push_str(&format!("{name} = {definition}\n"));
    }
    document
}

/// One member of a derived map: its key, whether it may be absent, and its
/// value's expression. Used by the derive.
#[doc(hidden)]
pub struct Member {
    pub key: u64,
    pub optional: bool,
    pub value: String,
}

/// The map of `members` in the order given, then every other key with any
/// value (`* any => any`): a derived map ignores the keys no field names. A
/// member's key is an integer value, whose colon form consumes the key
/// before its value is matched (RFC 8610, section 3.5.4), so a known key of
/// another type is never taken by the open member. Used by the derive.
#[doc(hidden)]
pub fn map(members: &[Member]) -> String {
    let mut entries: Vec<String> = members
        .iter()
        .map(|member| {
            let occurrence = if member.optional { "? " } else { "" };
            format!("{occurrence}{}: {}", member.key, member.value)
        })
        .collect();
    entries.push("* any => any".to_string());
    format!("{{ {} }}", entries.join(", "))
}

/// `inner` under tag `tag`, the only form a tagged derived type decodes.
/// Used by the derive.
#[doc(hidden)]
pub fn tagged(tag: u64, inner: &str) -> String {
    format!("#6.{tag}({inner})")
}

/// A unit variant: its bare discriminant. Used by the derive.
#[doc(hidden)]
pub fn unit_variant(discriminant: u64) -> String {
    discriminant.to_string()
}

/// A variant with a payload: the array of its discriminant and its payload's
/// items, a tuple variant's fields or a named variant's one map, exactly
/// that many. Used by the derive.
#[doc(hidden)]
pub fn variant(discriminant: u64, payload: &[String]) -> String {
    let mut items = vec![discriminant.to_string()];
    items.extend(payload.iter().cloned());
    format!("[{}]", items.join(", "))
}

/// The choice of `alternatives`, one of which a value is. Used by the
/// derive.
#[doc(hidden)]
pub fn choice(alternatives: &[String]) -> String {
    alternatives.join(" / ")
}

/// A unit struct: `null`. Used by the derive.
#[doc(hidden)]
pub fn unit() -> String {
    "null".to_string()
}

impl Cddl for bool {
    fn cddl(_: &mut Rules) -> String {
        "bool".to_string()
    }
}

/// An integer type's range, as its decoder accepts it (`int.rs`): every
/// integer from its `MIN` to its `MAX`, exactly; `u64` all of `uint`.
macro_rules! integer {
    ($($type:ty),+) => {
        $(impl Cddl for $type {
            fn cddl(_: &mut Rules) -> String {
                if (<$type>::MIN as i128) == 0 && (<$type>::MAX as u128) == u64::MAX as u128 {
                    "uint".to_string()
                } else {
                    format!("{}..{}", <$type>::MIN, <$type>::MAX)
                }
            }
        })+
    };
}

integer!(u8, u16, u32, u64, usize, i8, i16, i32, i64);

impl Cddl for String {
    fn cddl(_: &mut Rules) -> String {
        "tstr".to_string()
    }
}

impl Cddl for ByteString {
    fn cddl(_: &mut Rules) -> String {
        "bstr".to_string()
    }
}

impl Cddl for CBOR {
    fn cddl(_: &mut Rules) -> String {
        "any".to_string()
    }
}

/// A map of any keys and values; dCBOR keys are unique.
impl Cddl for Map {
    fn cddl(_: &mut Rules) -> String {
        "{ * any => any }".to_string()
    }
}

impl<T: Cddl> Cddl for Vec<T> {
    fn cddl(rules: &mut Rules) -> String {
        format!("[* {}]", T::cddl(rules))
    }
}

impl<T: Cddl> Cddl for VecDeque<T> {
    fn cddl(rules: &mut Rules) -> String {
        format!("[* {}]", T::cddl(rules))
    }
}

/// A table of the key's and value's expressions. The decoder refuses two
/// keys converting to one `K` (`map.rs`); for every key type with a rule
/// here, distinct dCBOR keys convert to distinct `K`, so the table admits
/// exactly what it accepts.
impl<K: Cddl, V: Cddl> Cddl for BTreeMap<K, V> {
    fn cddl(rules: &mut Rules) -> String {
        let key = K::cddl(rules);
        format!("{{ * {key} => {} }}", V::cddl(rules))
    }
}

/// As a B-tree map's ([`BTreeMap`]).
impl<K: Cddl, V: Cddl, S> Cddl for HashMap<K, V, S> {
    fn cddl(rules: &mut Rules) -> String {
        let key = K::cddl(rules);
        format!("{{ * {key} => {} }}", V::cddl(rules))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A type that contains itself, as a derived recursive type is
    /// described: its rule's name is known before its definition.
    struct Nested;
    impl Cddl for Nested {
        fn cddl(rules: &mut Rules) -> String {
            rules.rule::<Self>("Nested", |rules| {
                format!("[* {}]", <Nested as Cddl>::cddl(rules))
            })
        }
    }

    /// Two distinct types sharing one identifier.
    mod other {
        pub(super) struct Nested;
    }
    impl Cddl for other::Nested {
        fn cddl(rules: &mut Rules) -> String {
            rules.rule::<Self>("Nested", |_| "uint".to_string())
        }
    }

    /// Each primitive's expression is its decoder's accepted set; a
    /// container's is built from its element's.
    #[test]
    fn primitives_and_containers_name_their_accepted_sets() {
        let mut rules = Rules::new();
        assert_eq!(bool::cddl(&mut rules), "bool");
        assert_eq!(u8::cddl(&mut rules), "0..255");
        assert_eq!(u32::cddl(&mut rules), "0..4294967295");
        assert_eq!(u64::cddl(&mut rules), "uint");
        assert_eq!(i8::cddl(&mut rules), "-128..127");
        assert_eq!(
            i64::cddl(&mut rules),
            "-9223372036854775808..9223372036854775807"
        );
        assert_eq!(String::cddl(&mut rules), "tstr");
        assert_eq!(ByteString::cddl(&mut rules), "bstr");
        assert_eq!(CBOR::cddl(&mut rules), "any");
        assert_eq!(Vec::<u8>::cddl(&mut rules), "[* 0..255]");
        assert_eq!(
            BTreeMap::<String, u64>::cddl(&mut rules),
            "{ * tstr => uint }"
        );
        assert!(rules.rules.is_empty(), "a primitive defined a rule");
    }

    /// The derive's forms: a map's members in the order given, the open
    /// member last; a tag; variants; a choice; a unit struct.
    #[test]
    fn the_derive_forms_render_as_rfc_8610_writes_them() {
        let members = [
            Member {
                key: 0,
                optional: false,
                value: "tstr".into(),
            },
            Member {
                key: 2,
                optional: true,
                value: "uint".into(),
            },
        ];
        assert_eq!(map(&members), "{ 0: tstr, ? 2: uint, * any => any }");
        assert_eq!(map(&[]), "{ * any => any }");
        assert_eq!(tagged(42, "tstr"), "#6.42(tstr)");
        assert_eq!(unit_variant(3), "3");
        assert_eq!(
            variant(1, &["tstr".into(), "uint".into()]),
            "[1, tstr, uint]"
        );
        assert_eq!(choice(&["3".into(), "[1, tstr]".into()]), "3 / [1, tstr]");
        assert_eq!(unit(), "null");
    }

    /// A recursive type names its own rule; two types of one identifier get
    /// distinct rules, keyed by their `TypeId`s, not by their identifier or
    /// type name; the document's root comes first, each rule once. Two
    /// distinct types whose `type_name`s collide could not be constructed
    /// here (std documents that they may exist, without one being written in
    /// this crate's types); the key is the `TypeId`, so such a pair would be
    /// told apart as the two types of one identifier below are.
    #[test]
    fn rules_are_defined_once_each_named_apart() {
        assert_eq!(
            document::<Nested>(),
            "dcbor-root = Nested\nNested = [* Nested]\n"
        );
        let mut rules = Rules::new();
        assert_eq!(Nested::cddl(&mut rules), "Nested");
        assert_eq!(other::Nested::cddl(&mut rules), "Nested-2");
        assert_eq!(Nested::cddl(&mut rules), "Nested");
        assert_eq!(rules.rules.len(), 2);
    }
}
